```python
def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, the binary operators + - * /, parentheses, and spaces.
    * and / bind tighter than + and -, and operators of equal precedence associate left to right.
    Integer division truncates toward zero.
    Do not use eval or exec.
    """
    tokens = expr.split()
    values = []
    ops = []

    def calculate():
        op2 = values.pop()
        op1 = values.pop()
        op = ops.pop()
        if op == '+':
            values.append(op1 + op2)
        elif op == '-':
            values.append(op1 - op2)
        elif op == '*':
            values.append(op1 * op2)
        elif op == '/':
            values.append(int(op1 / op2))  # Integer division truncates toward zero


    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2
    }

    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            values.append(int(token))
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops[-1] != '(':
                calculate()
            ops.pop()
        elif token in precedence:
            while ops and ops[-1] != '(' and precedence.get(ops[-1], 0) >= precedence[token]:
                calculate()
            ops.append(token)
        i += 1

    while ops:
        calculate()

    return values[0]
