def roman_to_int(s: str) -> int:
    """Convert a valid uppercase Roman numeral (1 to 3999, using subtractive notation such as IV and CM) to an integer."""
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    prev_value = 0
    for i in range(len(s) - 1, -1, -1):
        curr_value = roman_map[s[i]]
        if curr_value < prev_value:
            result -= curr_value
        else:
            result += curr_value
        prev_value = curr_value
    return result
