```python
def summarize_ranges(nums: list[int]) -> list[str]:
    """
    Given a sorted list of distinct integers, return a list of strings describing its consecutive runs:
    'a-b' for a run from a to b with b > a, and 'a' for a single number.
    For example, [0,1,2,4,5,7] -> ['0-2', '4-5', '7'].
    """
    if not nums:
        return []

    result = []
    start = nums[0]
    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1] + 1:
            continue
        else:
            if start == nums[i-1]:
                result.append(str(start))
            else:
                result.append(str(start) + "-" + str(nums[i-1]))
            start = nums[i]
    if start == nums[-1]:
        result.append(str(start))
    else:
        result.append(str(start) + "-" + str(nums[-1]))
    return result
```

