def is_anagram(a: str, b: str) -> bool:
    """Return True if a and b contain the same letters with the same counts, ignoring spaces and case."""
    a = a.lower().replace(" ", "")
    b = b.lower().replace(" ", "")

    if len(a) != len(b):
        return False

    count_a = {}
    count_b = {}

    for char in a:
        count_a[char] = count_a.get(char, 0) + 1

    for char in b:
        count_b[char] = count_b.get(char, 0) + 1

    return count_a == count_b
```
