        if op == '+':
            return val1 + val2
        elif op == '-':
            return val1 - val2
        elif op == '*':
            return val1 * val2
        elif op == '/':
            if val2 == 0:
                raise ZeroDivisionError("Division by zero")
            return int(val1 / val2)  # Integer division truncates toward zero
        else:
            raise ValueError(f"Invalid operator: {op}")

    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            values.append(int(token))
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(val2, val1, op))
            ops.pop()  # Pop the '('
        elif token in '+-*/':
