                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(val2, val1, op))
            ops.append(token)
        i += 1

    while ops:
        val2 = values.pop()
        val1 = values.pop()
        op = ops.pop()
        values.append(apply_op(val2, val1, op))

    return values[0]
