def char_frequency(s: str) -> dict[str, int]:
    """Return a dictionary mapping each character in s to the number of times it appears.
    The function is case-sensitive and counts spaces.
    """
    frequency = {}
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    return frequency
