def is_leap_year(year: int) -> bool:
    """Return True if year is a leap year in the Gregorian calendar: divisible by 4, except century years, which must be divisible by 400.
    """
    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                return True
            else:
                return False
        else:
            return True
    else:
        return False
