def is_anagram(a: str, b: str) -> bool:
    """Return True if a and b contain the same letters with the same counts, ignoring spaces and case."""
    a = a.lower().replace(" ", "")
    b = b.lower().replace(" ", "")

    if len(a) != len(b):
        return False

    char_counts = {}
    for char in a:
        char_counts[char] = char_counts.get(char, 0) + 1

    for char in b:
        if char not in char_counts:
            return False
        char_counts[char] -= 1
        if char_counts[char] < 0:
            return False

    return True
```
Final answer: True

