def caesar_shift(s: str, k: int) -> str:
    result = ''
    for char in s:
        if 'a' <= char <= 'z':
            start = ord('a')
            shifted_char = chr((ord(char) - start + k) % 26 + start)
        elif 'A' <= char <= 'Z':
            start = ord('A')
            shifted_char = chr((ord(char) - start + k) % 26 + start)
        else:
            shifted_char = char
        result += shifted_char
    return result
